@namespace sv_5a33747d412642efa377de059af7e0eb.Components.Pages.Apply

<div class="step-content">
    <h3>Personal Information</h3>

    <div class="form-group">
        <label>Full Name *</label>
        <input type="text" @bind="FullName" @bind:event="onchange" />
    </div>
    <div class="form-group">
        <label>Email *</label>
        <input type="email" @bind="Email" @bind:event="onchange" />
        @if (!string.IsNullOrEmpty(_emailError))
        {
            <span class="error">@_emailError</span>
        }
    </div>
    <div class="form-group">
        <label>Phone *</label>
        <input type="tel" @bind="Phone" @bind:event="onchange" />
    </div>
    <div class="form-group">
        <label>Address *</label>
        <textarea rows="2" @bind="Address" @bind:event="onchange"></textarea>
    </div>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="error">@_validationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-primary" @onclick="HandleNext" disabled="@_isValidating">
            @(_isValidating ? "Validating..." : "Next")
        </button>
    </div>
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public EventCallback<PersonalInfoData> OnNext { get; set; }
    [Parameter] public Func<string, Task<bool>>? ValidateEmail { get; set; }

    private string _validationError = "";
    private string _emailError = "";
    private bool _isValidating;

    private async Task HandleNext()
    {
        _validationError = "";
        _emailError = "";

        if (string.IsNullOrWhiteSpace(FullName) || string.IsNullOrWhiteSpace(Email)
            || string.IsNullOrWhiteSpace(Phone) || string.IsNullOrWhiteSpace(Address))
        {
            _validationError = "All fields are required.";
            return;
        }

        if (ValidateEmail is not null)
        {
            _isValidating = true;
            StateHasChanged();
            var isValid = await ValidateEmail(Email);
            _isValidating = false;
            if (!isValid)
            {
                _emailError = "Please enter a valid email address.";
                return;
            }
        }

        await OnNext.InvokeAsync(new PersonalInfoData(FullName, Email, Phone, Address));
    }

    public record PersonalInfoData(string FullName, string Email, string Phone, string Address);
}

@namespace sv_5a33747d412642efa377de059af7e0eb.Components.Pages.Apply

<div class="step-content">
    <h3>Work History</h3>

    @for (int i = 0; i < Entries.Count; i++)
    {
        var index = i;
        var entry = Entries[index];
        <div class="entry-card">
            <h4>Position @(index + 1)</h4>
            <WorkEntryForm
                Company="@entry.Company"
                Title="@entry.Title"
                StartDate="@entry.StartDate"
                EndDate="@entry.EndDate"
                IsCurrent="@entry.IsCurrent"
                Description="@entry.Description"
                ShowRemove="@(Entries.Count > 1)"
                OnRemove="() => RemoveEntry(index)"
                OnChanged="data => UpdateEntry(index, data)" />
        </div>
    }

    <button type="button" class="btn-secondary" @onclick="AddEntry">+ Add Another Position</button>

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="error">@_validationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<EntryModel> Entries { get; set; } = new();
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<List<EntryModel>> OnNext { get; set; }

    private string _validationError = "";

    protected override void OnInitialized()
    {
        if (Entries.Count == 0)
        {
            Entries.Add(new EntryModel());
        }
    }

    private void AddEntry()
    {
        Entries.Add(new EntryModel());
    }

    private void RemoveEntry(int index)
    {
        if (Entries.Count > 1)
        {
            Entries.RemoveAt(index);
        }
    }

    private void UpdateEntry(int index, WorkEntryForm.WorkEntryData data)
    {
        if (index < Entries.Count)
        {
            Entries[index] = new EntryModel
            {
                Company = data.Company,
                Title = data.Title,
                StartDate = data.StartDate,
                EndDate = data.IsCurrent ? null : data.EndDate,
                IsCurrent = data.IsCurrent,
                Description = data.Description
            };
        }
    }

    private async Task HandleNext()
    {
        _validationError = "";
        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                _validationError = "Company and Job Title are required for each position.";
                return;
            }
        }
        await OnNext.InvokeAsync(Entries);
    }

    public class EntryModel
    {
        public string Company { get; set; } = "";
        public string Title { get; set; } = "";
        public DateTime StartDate { get; set; } = DateTime.Today;
        public DateTime? EndDate { get; set; }
        public bool IsCurrent { get; set; }
        public string Description { get; set; } = "";
    }
}

@namespace sv_5a33747d412642efa377de059af7e0eb.Components.Pages.Apply

<div class="step-content">
    <h3>References</h3>
    <p>Please provide 2-3 professional references.</p>

    @for (int i = 0; i < References.Count; i++)
    {
        var index = i;
        var reference = References[index];
        <div class="entry-card">
            <h4>Reference @(index + 1)</h4>
            <ReferenceForm
                Name="@reference.Name"
                Relationship="@reference.Relationship"
                Email="@reference.Email"
                Phone="@reference.Phone"
                ShowRemove="@(References.Count > 2)"
                OnRemove="() => RemoveReference(index)"
                OnChanged="data => UpdateReference(index, data)" />
        </div>
    }

    @if (References.Count < 3)
    {
        <button type="button" class="btn-secondary" @onclick="AddReference">+ Add Reference</button>
    }

    @if (!string.IsNullOrEmpty(_validationError))
    {
        <div class="error">@_validationError</div>
    }

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public List<ReferenceModel> References { get; set; } = new();
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<List<ReferenceModel>> OnNext { get; set; }

    private string _validationError = "";

    protected override void OnInitialized()
    {
        while (References.Count < 2)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void AddReference()
    {
        if (References.Count < 3)
        {
            References.Add(new ReferenceModel());
        }
    }

    private void RemoveReference(int index)
    {
        if (References.Count > 2)
        {
            References.RemoveAt(index);
        }
    }

    private void UpdateReference(int index, ReferenceForm.ReferenceData data)
    {
        if (index < References.Count)
        {
            References[index] = new ReferenceModel
            {
                Name = data.Name,
                Relationship = data.Relationship,
                Email = data.Email,
                Phone = data.Phone
            };
        }
    }

    private async Task HandleNext()
    {
        _validationError = "";
        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) || string.IsNullOrWhiteSpace(r.Relationship)
                || string.IsNullOrWhiteSpace(r.Email) || string.IsNullOrWhiteSpace(r.Phone))
            {
                _validationError = "All fields are required for each reference.";
                return;
            }
        }
        await OnNext.InvokeAsync(References);
    }

    public class ReferenceModel
    {
        public string Name { get; set; } = "";
        public string Relationship { get; set; } = "";
        public string Email { get; set; } = "";
        public string Phone { get; set; } = "";
    }
}

@namespace sv_5a33747d412642efa377de059af7e0eb.Components.Pages.Apply

<div class="step-content">
    <h3>Cover Letter</h3>

    <div class="form-group">
        <label>Write your cover letter below:</label>
        <textarea rows="12" maxlength="2000" @bind="CoverLetter" @bind:event="oninput"></textarea>
        <div class="char-count">@CoverLetter.Length / 2000 characters</div>
    </div>

    <div class="step-buttons">
        <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
        <button type="button" class="btn-primary" @onclick="HandleNext">Next</button>
    </div>
</div>

@code {
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<string> OnNext { get; set; }

    private async Task HandleNext()
    {
        await OnNext.InvokeAsync(CoverLetter);
    }
}

@namespace sv_5a33747d412642efa377de059af7e0eb.Components.Pages.Apply

<div class="step-content">
    <h3>Review & Submit</h3>

    @if (_submitted)
    {
        <div class="confirmation">
            <h4>&#10003; Application Submitted Successfully!</h4>
            <p>Your application ID is: <strong>@_applicationId</strong></p>
            <p>Thank you for applying. We will be in touch soon.</p>
        </div>
    }
    else
    {
        <div class="review-section">
            <div class="review-header">
                <h4>Personal Information</h4>
                <a href="javascript:void(0)" @onclick='() => OnEdit.InvokeAsync(0)'>Edit</a>
            </div>
            <dl>
                <dt>Name</dt><dd>@FullName</dd>
                <dt>Email</dt><dd>@Email</dd>
                <dt>Phone</dt><dd>@Phone</dd>
                <dt>Address</dt><dd>@Address</dd>
            </dl>
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>Work History</h4>
                <a href="javascript:void(0)" @onclick='() => OnEdit.InvokeAsync(1)'>Edit</a>
            </div>
            @foreach (var entry in WorkEntries)
            {
                <div class="review-entry">
                    <strong>@entry.Title</strong> at @entry.Company
                    <br />
                    <small>@entry.StartDate.ToString("MMM yyyy") — @(entry.IsCurrent ? "Present" : entry.EndDate?.ToString("MMM yyyy") ?? "N/A")</small>
                    @if (!string.IsNullOrWhiteSpace(entry.Description))
                    {
                        <p>@entry.Description</p>
                    }
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>References</h4>
                <a href="javascript:void(0)" @onclick='() => OnEdit.InvokeAsync(2)'>Edit</a>
            </div>
            @foreach (var r in References)
            {
                <div class="review-entry">
                    <strong>@r.Name</strong> (@r.Relationship)
                    <br />
                    <small>@r.Email | @r.Phone</small>
                </div>
            }
        </div>

        <div class="review-section">
            <div class="review-header">
                <h4>Cover Letter</h4>
                <a href="javascript:void(0)" @onclick='() => OnEdit.InvokeAsync(3)'>Edit</a>
            </div>
            <p class="cover-letter-preview">@CoverLetter</p>
        </div>

        @if (!string.IsNullOrEmpty(_errorMessage))
        {
            <div class="error">@_errorMessage</div>
        }

        <div class="step-buttons">
            <button type="button" class="btn-outline" @onclick="OnBack">Back</button>
            <button type="button" class="btn-primary btn-submit" @onclick="HandleSubmit" disabled="@_isSubmitting">
                @(_isSubmitting ? "Submitting..." : "Submit Application")
            </button>
        </div>
    }
</div>

@code {
    [Parameter] public string FullName { get; set; } = "";
    [Parameter] public string Email { get; set; } = "";
    [Parameter] public string Phone { get; set; } = "";
    [Parameter] public string Address { get; set; } = "";
    [Parameter] public List<WorkHistoryStep.EntryModel> WorkEntries { get; set; } = new();
    [Parameter] public List<ReferencesStep.ReferenceModel> References { get; set; } = new();
    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<int> OnEdit { get; set; }
    [Parameter] public Func<Task<int>>? OnSubmit { get; set; }

    private bool _isSubmitting;
    private bool _submitted;
    private int _applicationId;
    private string _errorMessage = "";

    private async Task HandleSubmit()
    {
        if (OnSubmit is null) return;

        _isSubmitting = true;
        _errorMessage = "";
        StateHasChanged();

        try
        {
            _applicationId = await OnSubmit();
            _submitted = true;
        }
        catch (Exception ex)
        {
            _errorMessage = $"Submission failed: {ex.Message}";
        }
        finally
        {
            _isSubmitting = false;
        }
    }
}

