@page "/apply"
@using sv_5a33747d412642efa377de059af7e0eb.Components.Pages.Apply
@using sv_5a33747d412642efa377de059af7e0eb.Models
@rendermode InteractiveServer
@inject IApplicationService ApplicationService

<PageTitle>Job Application</PageTitle>

<div class="application-form">
    <h2>Job Application</h2>

    <StepIndicator CurrentStep="_currentStep" OnNavigateToStep="NavigateToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep
                FullName="@_fullName"
                Email="@_email"
                Phone="@_phone"
                Address="@_address"
                ValidateEmail="ApplicationService.ValidateEmailAsync"
                OnNext="HandlePersonalInfoNext" />
            break;
        case 1:
            <WorkHistoryStep
                Entries="_workEntries"
                OnBack="() => _currentStep = 0"
                OnNext="HandleWorkHistoryNext" />
            break;
        case 2:
            <ReferencesStep
                References="_references"
                OnBack="() => _currentStep = 1"
                OnNext="HandleReferencesNext" />
            break;
        case 3:
            <CoverLetterStep
                CoverLetter="@_coverLetter"
                OnBack="() => _currentStep = 2"
                OnNext="HandleCoverLetterNext" />
            break;
        case 4:
            <ReviewStep
                FullName="@_fullName"
                Email="@_email"
                Phone="@_phone"
                Address="@_address"
                WorkEntries="_workEntries"
                References="_references"
                CoverLetter="@_coverLetter"
                OnBack="() => _currentStep = 3"
                OnEdit="NavigateToStep"
                OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private string _fullName = "";
    private string _email = "";
    private string _phone = "";
    private string _address = "";
    private List<WorkHistoryStep.EntryModel> _workEntries = new();
    private List<ReferencesStep.ReferenceModel> _references = new();
    private string _coverLetter = "";

    private void NavigateToStep(int step)
    {
        if (step >= 0 && step <= 4)
        {
            _currentStep = step;
        }
    }

    private void HandlePersonalInfoNext(PersonalInfoStep.PersonalInfoData data)
    {
        _fullName = data.FullName;
        _email = data.Email;
        _phone = data.Phone;
        _address = data.Address;
        _currentStep = 1;
    }

    private void HandleWorkHistoryNext(List<WorkHistoryStep.EntryModel> entries)
    {
        _workEntries = entries;
        _currentStep = 2;
    }

    private void HandleReferencesNext(List<ReferencesStep.ReferenceModel> references)
    {
        _references = references;
        _currentStep = 3;
    }

    private void HandleCoverLetterNext(string coverLetter)
    {
        _coverLetter = coverLetter;
        _currentStep = 4;
    }

    private async Task<int> SubmitApplication()
    {
        var personal = new PersonalInfo(_fullName, _email, _phone, _address);
        var workHistory = new WorkHistory(
            _workEntries.Select(e => new WorkEntry(e.Company, e.Title, e.StartDate, e.EndDate, e.Description)).ToList()
        );
        var references = _references.Select(r => new Reference(r.Name, r.Relationship, r.Email, r.Phone)).ToList();
        var application = new JobApplication(personal, workHistory, references, _coverLetter);

        return await ApplicationService.SubmitApplicationAsync(application);
    }
}

.application-form {
    max-width: 800px;
    margin: 2rem auto;
    padding: 2rem;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    min-width: 80px;
}

.step.completed {
    cursor: pointer;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: white;
    color: #6c757d;
    transition: all 0.2s;
}

.step.active .step-circle {
    background: #0d6efd;
    border-color: #0d6efd;
    color: white;
}

.step.completed .step-circle {
    background: #198754;
    border-color: #198754;
    color: white;
}

.step.dimmed .step-circle {
    opacity: 0.5;
}

